    h.app.services.write_shared = Some(Arc::new(|p: &str, bytes: &[u8]| {
        std::thread::sleep(Duration::from_millis(300)); // a slow disk: still writing at the drop
        lightcraft_engine::export::write_file(p, bytes)
    }));
    let m = marker.clone();
